1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * The single definition of the fiscal year, which starts on 1 July. A date on or after
8	 * 1 July belongs to the fiscal year beginning in that calendar year; a date before 1 July
9	 * belongs to the fiscal year that began the previous calendar year. A fiscal year is
10	 * identified by the calendar year in which it starts and labelled {@code "FY<YY>"} from that
11	 * year's last two digits (e.g. 1 July 2026 – 30 June 2027 is {@code "FY26"}).
12	 *
13	 * <p>Provides the fiscal basis for every date-derived value: the membership number's year
14	 * segment and the {@code fiscalYear} field (both via {@code OwnerMapper}), and an owner's
15	 * {@link Tenure tenure} measured in elapsed fiscal years.
16	 */
17	public final class FiscalYear {
18	
19	    /** First month of the fiscal year. */
20	    private static final Month FISCAL_YEAR_START = Month.JULY;
21	
22	    private FiscalYear() {
23	    }
24	
25	    /** The calendar year in which the fiscal year containing {@code date} begins. */
26	    static int startYear(LocalDate date) {
27	        int year = date.getYear();
28	        return date.getMonthValue() >= FISCAL_YEAR_START.getValue() ? year : year - 1;
29	    }
30	
31	    /** The last two digits of the starting calendar year of the fiscal year containing
32	     *  {@code date} — the {@code YY} shared by the fiscal-year label and the membership number. */
33	    public static int shortYear(LocalDate date) {
34	        return startYear(date) % 100;
35	    }
36	
37	    /** The fiscal-year label {@code "FY<YY>"} for {@code date}, or {@code null} when the date
38	     *  is absent. */
39	    public static String label(LocalDate date) {
40	        return date == null ? null : String.format("FY%02d", shortYear(date));
41	    }
42	
43	    /** Whole fiscal years elapsed from {@code from} to {@code to} — the number of 1 July
44	     *  boundaries crossed — never negative. Both dates must be non-null. */
45	    static long between(LocalDate from, LocalDate to) {
46	        return Math.max((long) startYear(to) - startYear(from), 0);
47	    }
48	}
