1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * The single definition of an owner's "tenure": the number of whole {@link FiscalYear fiscal
7	 * years} that have elapsed since the owner's registration date. An owner registered in the
8	 * current fiscal year has zero tenure; each 1 July boundary since registration adds one.
9	 * Provides the measure {@link AssignMembershipLevel} uses to gate the top membership level,
10	 * which is reserved for long-standing owners.
11	 */
12	final class Tenure {
13	
14	    private Tenure() {
15	    }
16	
17	    /** Whole fiscal years elapsed between {@code registrationDate} and {@code asOf}; zero when
18	     *  the date is unset or still in the future. */
19	    static long fiscalYears(LocalDate registrationDate, LocalDate asOf) {
20	        if (registrationDate == null) {
21	            return 0;
22	        }
23	        return FiscalYear.between(registrationDate, asOf);
24	    }
25	}
