26	/**
27	 * Maps Owner & OwnerDto using Mapstruct
28	 */
29	@Mapper(uses = PetMapper.class)
30	public interface OwnerMapper {
31	
32	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
33	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
34	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
35	    @Mapping(target = "initials", expression = "java(initials(owner))")
36	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
37	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
38	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
39	    @Mapping(target = "locality", expression = "java(locality(owner))")
40	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
41	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
42	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
43	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
44	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
45	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
46	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
47	    OwnerDto toOwnerDto(Owner owner);
48	
49	    /** The owner's canonical API path, formatted '/api/owners/&lt;id&gt;'; absent until the owner
50	     *  has been persisted and assigned an id. */
51	    default String selfLink(Owner owner) {
52	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
53	    }
54	
55	    /** The owner's stored E.164 telephone formatted for humans; see {@link TelephoneDisplay}. */
56	    default String telephoneDisplay(Owner owner) {
57	        return TelephoneDisplay.of(owner.getTelephone());
58	    }
59	
60	    /** The owner's derived identity key: normalized telephone, email and household id joined. */
61	    default String identityKey(Owner owner) {
62	        return IdentityKey.of(owner);
63	    }
64	
65	    /** Whether the owner was flagged as a possible duplicate at registration, i.e. it carries
66	     *  the id of an existing owner it possibly duplicates. */
67	    default boolean possibleDuplicate(Owner owner) {
68	        return owner.getPossibleDuplicateOf() != null;
69	    }
70	
71	    /** The owner's salutation: the optional title prefixed to the last name, or the last name
72	     *  alone when no title is on file; see {@link Salutation}. */
73	    default String salutation(Owner owner) {
74	        return Salutation.of(owner.getTitle(), owner.getLastName());
75	    }
76	
77	    /** Format an owner's name for display as 'LastName, FirstName'. */
78	    default String displayName(Owner owner) {
79	        return owner.getLastName() + ", " + owner.getFirstName();
80	    }
81	
82	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
83	    default String initials(Owner owner) {
84	        return initial(owner.getFirstName()) + initial(owner.getLastName());
85	    }
86	
87	    private String initial(String name) {
88	        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
89	    }
90	
91	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
92	     *  fiscal year of the registration date (see {@link FiscalYear}, e.g. 'SPR-SMI-0007-M26').
93	     *  Absent until both the customer code and registration date have been assigned. */
94	    default String membershipNumber(Owner owner) {
95	        String customerCode = owner.getCustomerCode();
96	        LocalDate registrationDate = owner.getRegistrationDate();
97	        if (customerCode == null || registrationDate == null) {
98	            return null;
99	        }
100	        return String.format("%s-M%02d", customerCode, FiscalYear.shortYear(registrationDate));
101	    }
102	
103	    /** The owner's fiscal year, formatted 'FY&lt;YY&gt;' from the fiscal year of the
104	     *  registration date (see {@link FiscalYear}); absent until the registration date is set. */
105	    default String fiscalYear(Owner owner) {
106	        return FiscalYear.label(owner.getRegistrationDate());
107	    }
108	
109	    /** The Luhn check digit (0-9) over the digits of the owner's customerCode; absent until the
110	     *  customer code has been assigned. */
111	    default Integer checkDigit(Owner owner) {
112	        String customerCode = owner.getCustomerCode();
113	        return customerCode == null ? null : Luhn.checkDigit(customerCode);
114	    }
115	
116	    /** The owner's region, read back from the region segment of its customerCode (the identity's
117	     *  {@code <REGION>-<HASH8>} form). Until the customer code has been assigned it falls back to
118	     *  deriving the region from the postcode range first (NSW 2000-2099, VIC 3000-3099,
119	     *  QLD 4000-4099), then the city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
120	     *  Brisbane-&gt;QLD), or 'UNKNOWN' otherwise. */
121	    default String locality(Owner owner) {
