5	/**
6	 * The single definition of an owner's primary identifier: the stable code that identifies
7	 * the owner across the system and in its audit trail. Today this is the
8	 * {@link Owner#getCustomerCode() customerCode}; when the customerCode is later unified into
9	 * the memberId, changing this one method makes every consumer (the {@link OwnerCreatedEvent}
10	 * included) carry the memberId instead.
11	 */
12	public final class OwnerIdentity {
13	
14	    private OwnerIdentity() {
15	    }
16	
17	    /** The owner's current primary identifier. */
