package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * The single definition of the project's SHA-256 hashing over the UTF-8 bytes of a string.
 * The owner {@link CustomerCode customer code} and {@link Household household identifier} take
 * the first {@code length} upper-case hex characters; the owner {@link IdentityKey} takes the
 * full lower-case digest — all share one implementation rather than each rolling their own.
 *
 * <p>Pure function of its inputs; no state.
 */
final class Sha256 {

    private Sha256() {
    }

    /** The first {@code length} upper-case hex characters of SHA-256 over {@code value}. */
    static String hex(String value, int length) {
        byte[] digest = digest(value);
        StringBuilder hex = new StringBuilder(length);
        for (int i = 0; hex.length() < length; i++) {
            hex.append(String.format("%02X", digest[i]));
        }
        return hex.substring(0, length);
    }

    /** The full 64-character lower-case hex SHA-256 of {@code value}. */
    static String hexLower(String value) {
        byte[] digest = digest(value);
        StringBuilder hex = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            hex.append(String.format("%02x", b));
        }
        return hex.toString();
    }

    private static byte[] digest(String value) {
        try {
            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 is required but unavailable", e);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of two owners being in the same city, compared case-insensitively
 * (leading and trailing whitespace ignored). Provides the membership test used to count how
 * many existing owners already live in a new owner's city.
 *
 * @see AssignOwnerCustomerCode derives the per-city sequence of the customer code.
 */
final class SameCity {

    private SameCity() {
    }

    /** Whether {@code owner} is in {@code city}. */
    static boolean matches(Owner owner, String city) {
        return normalize(owner.getCity()).equals(normalize(city));
    }

    /** How many of {@code owners} are in {@code city}. */
    static int count(Iterable<Owner> owners, String city) {
        int inCity = 0;
        for (Owner owner : owners) {
            if (matches(owner, city)) {
                inCity++;
            }
        }
        return inCity;
    }

    /** A city name trimmed and lower-cased, so comparison is case-insensitive. */
    private static String normalize(String value) {
        return value == null ? "" : value.strip().toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.time.Month;

/**
 * The single definition of the fiscal year, which starts on 1 July. A date on or after
 * 1 July belongs to the fiscal year beginning in that calendar year; a date before 1 July
 * belongs to the fiscal year that began the previous calendar year. A fiscal year is
 * identified by the calendar year in which it starts and labelled {@code "FY<YY>"} from that
 * year's last two digits (e.g. 1 July 2026 – 30 June 2027 is {@code "FY26"}).
 *
 * <p>Provides the fiscal basis for every date-derived value: the membership number's year
 * segment and the {@code fiscalYear} field (both via {@code OwnerMapper}), and an owner's
 * {@link Tenure tenure} measured in elapsed fiscal years.
 */
public final class FiscalYear {

    /** First month of the fiscal year. */
    private static final Month FISCAL_YEAR_START = Month.JULY;

    private FiscalYear() {
    }

    /** The calendar year in which the fiscal year containing {@code date} begins. */
    static int startYear(LocalDate date) {
        int year = date.getYear();
        return date.getMonthValue() >= FISCAL_YEAR_START.getValue() ? year : year - 1;
    }

    /** The last two digits of the starting calendar year of the fiscal year containing
     *  {@code date} — the {@code YY} shared by the fiscal-year label and the membership number. */
    public static int shortYear(LocalDate date) {
        return startYear(date) % 100;
    }

    /** The fiscal-year label {@code "FY<YY>"} for {@code date}, or {@code null} when the date
     *  is absent. */
    public static String label(LocalDate date) {
        return date == null ? null : String.format("FY%02d", shortYear(date));
    }

    /** Whole fiscal years elapsed from {@code from} to {@code to} — the number of 1 July
     *  boundaries crossed — never negative. Both dates must be non-null. */
    static long between(LocalDate from, LocalDate to) {
        return Math.max((long) startYear(to) - startYear(from), 0);
    }
}

